import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1787871741000}'),r={name:"troubleshooting.md"};function s(n,e,l,h,p,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="the-emulator-has-no-internet" tabindex="-1">The emulator has no internet <a class="header-anchor" href="#the-emulator-has-no-internet" aria-label="Permalink to &quot;The emulator has no internet&quot;">​</a></h2><p>Most likely a <strong>dead proxy</strong>: the global proxy points at a port where nothing listens anymore (a previous session that didn&#39;t clean up). Beholder clears these automatically on launch — but if it persists:</p><ol><li>Open <strong>Emulators → Doctor</strong> on the running emulator</li><li>The <em>HTTP proxy</em> check reports dead ports in red</li><li>Click <strong>Fix</strong> (or <strong>Fix all issues</strong>)</li></ol><p>Manual equivalent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http_proxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :0</span></span></code></pre></div><h2 id="your-connection-is-not-private-in-the-emulator-browser" tabindex="-1">&quot;Your connection is not private&quot; in the emulator browser <a class="header-anchor" href="#your-connection-is-not-private-in-the-emulator-browser" aria-label="Permalink to &quot;&quot;Your connection is not private&quot; in the emulator browser&quot;">​</a></h2><p>The app or browser does not trust the Beholder CA yet:</p><ol><li>Restart the browser or app — Android processes cache the certificate store in memory, so anything running before the CA was installed keeps rejecting it</li><li>Run <strong>Doctor</strong> and confirm the <em>Beholder CA</em> check passes</li><li>Apps with certificate pinning (for example the Facebook app) reject any proxy by design — your own React Native app and the browser will not</li></ol><h2 id="adb-root-failed" tabindex="-1">&quot;adb root failed&quot; <a class="header-anchor" href="#adb-root-failed" aria-label="Permalink to &quot;&quot;adb root failed&quot;&quot;">​</a></h2><ul><li><strong>Google Play image</strong> — refuses root; recreate the emulator with a <code>google_apis</code> image from the wizard</li><li><strong>&quot;adbd is already running as root&quot;</strong> — this is success, not an error; Beholder handles it</li><li>Anything else — the error includes the raw adb output; copy it from the error box before reporting an issue</li></ul><h2 id="no-traffic-appears" tabindex="-1">No traffic appears <a class="header-anchor" href="#no-traffic-appears" aria-label="Permalink to &quot;No traffic appears&quot;">​</a></h2><ul><li>React Native apps in development make no requests until the <strong>Metro bundle loads</strong> — wait for it, then use the app</li><li>Check that Capture is active (green pulsing dot in the command bar)</li><li>Some traffic uses certificate pinning and will show as failed connections — that traffic is intentionally unproxyable</li></ul><h2 id="websocket-frames-missing" tabindex="-1">WebSocket frames missing <a class="header-anchor" href="#websocket-frames-missing" aria-label="Permalink to &quot;WebSocket frames missing&quot;">​</a></h2><p>WebSocket interception is best-effort. HTTP, HTTPS, and SSE are the core path; if frames do not appear for a specific library, open an issue with the library and URL involved.</p><h2 id="something-else" tabindex="-1">Something else <a class="header-anchor" href="#something-else" aria-label="Permalink to &quot;Something else&quot;">​</a></h2><p>Run <strong>Doctor</strong> first — its output is designed to identify the failing layer (device, root, network, proxy, CA). The error boxes throughout the app include a copy button for attaching exact messages to bug reports.</p>',17)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
